#!/bin/sh
# tools/resolve-rebase.sh — drive an in-progress rebase in a worktree to completion
# for the whitelisted generated/workflow paths; anything else stays manual.
#
# Usage: sh tools/resolve-rebase.sh <worktree-path>
#
# Whitelist (all taken with `git checkout --ours` — during a rebase "ours" is the new
# base, i.e. main):
#   tickets/BOARD.md, tickets/GRAPH.md, tickets/index.json   (regenerated by tickets.py sync)
#   tickets/DS-*.md                                          (main's ticket state wins)
#   Cargo.lock                                               (ours, then regenerated with
#                                                             `cargo generate-lockfile --offline`;
#                                                             DS_LOCKFILE_ONLINE=1 retries online)
#
# Exit codes:
#   0  rebase finished (every conflict was whitelisted and resolved)
#   2  no rebase in progress in <worktree-path> (or bad usage / not a git worktree)
#   3  an unmerged path is outside the whitelist (paths printed; rebase left untouched)
#   4  lockfile regeneration failed, loop cap (20) hit, or a git error (loud failure)
set -u

WT=${1:-}
[ -n "$WT" ] || { echo "usage: sh tools/resolve-rebase.sh <worktree-path>" >&2; exit 2; }
git -C "$WT" rev-parse --git-dir >/dev/null 2>&1 || {
  echo "resolve-rebase: '$WT' is not a git worktree" >&2
  exit 2
}

gitpath() { # gitpath <name> -> absolute path of $GIT_DIR/<name>
  p=$(git -C "$WT" rev-parse --git-path "$1") || return 1
  case "$p" in /*) printf '%s\n' "$p" ;; *) printf '%s\n' "$WT/$p" ;; esac
}

rebase_in_progress() {
  [ -d "$(gitpath rebase-merge)" ] && return 0
  [ -d "$(gitpath rebase-apply)" ] && return 0
  return 1
}

rebase_in_progress || {
  echo "resolve-rebase: no rebase in progress in $WT" >&2
  exit 2
}

MAX_ITER=20
iter=0
resolved_tickets=0
TMP=$(mktemp -d) || { echo "resolve-rebase: mktemp failed" >&2; exit 4; }
trap 'rm -rf "$TMP"' EXIT

while rebase_in_progress; do
  iter=$((iter + 1))
  if [ "$iter" -gt "$MAX_ITER" ]; then
    echo "resolve-rebase: FAIL — still resolving after $MAX_ITER iterations; rebase in $WT left in progress, resolve manually" >&2
    exit 4
  fi

  git -C "$WT" diff --name-only --diff-filter=U > "$TMP/unmerged" || {
    echo "resolve-rebase: git diff --diff-filter=U failed in $WT" >&2
    exit 4
  }

  if [ ! -s "$TMP/unmerged" ]; then
    # nothing unmerged but the rebase is still open (resolution staged, awaiting --continue)
    GIT_EDITOR=true git -C "$WT" rebase --continue >/dev/null 2>&1 || true
    continue
  fi

  # classify every unmerged path BEFORE touching anything: one path outside the
  # whitelist aborts with the rebase untouched
  bad=0
  while IFS= read -r p; do
    case "$p" in
      tickets/BOARD.md|tickets/GRAPH.md|tickets/index.json|tickets/DS-*.md|Cargo.lock) ;;
      *) echo "resolve-rebase: unmerged path outside whitelist: $p" >&2; bad=1 ;;
    esac
  done < "$TMP/unmerged"
  if [ "$bad" -ne 0 ]; then
    echo "resolve-rebase: rebase left untouched in $WT; resolve the path(s) above manually, then: GIT_EDITOR=true git -C $WT rebase --continue" >&2
    exit 3
  fi

  lock=0
  while IFS= read -r p; do
    git -C "$WT" checkout --ours -- "$p" || {
      echo "resolve-rebase: checkout --ours failed for $p" >&2
      exit 4
    }
    case "$p" in
      Cargo.lock) lock=1 ;;
      tickets/*) resolved_tickets=1 ;;
    esac
  done < "$TMP/unmerged"

  if [ "$lock" -eq 1 ]; then
    if (cd "$WT" && cargo generate-lockfile --offline); then
      :
    elif [ "${DS_LOCKFILE_ONLINE:-0}" = "1" ]; then
      echo "resolve-rebase: offline generate-lockfile failed; retrying online (DS_LOCKFILE_ONLINE=1)" >&2
      (cd "$WT" && cargo generate-lockfile) || {
        echo "resolve-rebase: cargo generate-lockfile failed in $WT — rebase left in progress" >&2
        exit 4
      }
    else
      echo "resolve-rebase: cargo generate-lockfile --offline failed in $WT (set DS_LOCKFILE_ONLINE=1 to retry online) — rebase left in progress" >&2
      exit 4
    fi
  fi

  while IFS= read -r p; do
    git -C "$WT" add -- "$p" || {
      echo "resolve-rebase: git add failed for $p" >&2
      exit 4
    }
  done < "$TMP/unmerged"

  # a new conflict makes this exit nonzero; the loop picks it up on the next pass
  GIT_EDITOR=true git -C "$WT" rebase --continue >/dev/null 2>&1 || true
done

# The board files were taken from main, but the replayed commits still carry the
# branch's generated copies, so BOARD/GRAPH/index can end up stale against the
# ticket files. Normalize once the rebase is done.
if [ "$resolved_tickets" -eq 1 ] && [ -f "$WT/tools/tickets.py" ]; then
  (cd "$WT" && python3 tools/tickets.py sync >/dev/null) || {
    echo "resolve-rebase: tickets.py sync failed in $WT — generated board may be stale" >&2
    exit 4
  }
fi

echo "resolve-rebase: rebase finished in $WT"
exit 0
